css:
@page {
    size: A4;
}

.page-break {
    page-break-after : always;
}

@media print {
    button,
    .btn,
    .print-hide,
    .no-print,
    .form-control,
    .input-group,
    .dropdown,
    .actions,
    .navbar,
    .sidebar {
        display: none !important;
    }

}

.header{
    text-align: center;
    font-size: 26px;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    padding: 10px 0;
    border-bottom: 3px solid #222;
    margin-bottom: 20px;
}

.footer{
    text-align: center;
    font-size: 12px;
    padding-top: 10px;
    border-top: 2px solid #222;
    margin-top: 30px;
    color: #333;
    }
